import {form,number as num,select as sel,text,area,field,result,outputText,e,n,error,download} from '../ui.mjs';
import {attendance,ohm,projectile,authorNames} from './calc-core.mjs';
import {need,optional,today,table,timerDisplay,localChoice} from './shared.mjs';
export function setupLearning(tool,mount,out){const id=tool.id,show=o=>result(out,o);if(id==='typing-test')return typing(mount,out);if(id==='flashcards')return flashcards(mount,out);const forms={
 'negative-marking':()=>form(mount,[num('total','Total questions',100,1,10000,1),num('correct','Correct answers',60,0,10000,1),num('wrong','Incorrect answers',20,0,10000,1),num('marks','Marks for a correct answer',1,0,100),num('penalty','Marks deducted per wrong answer',.25,0,100)],v=>{need(+v.correct+ +v.wrong<=+v.total,'Correct and incorrect answers cannot exceed total questions.');const r=+v.correct*+v.marks-+v.wrong*+v.penalty;show({label:'Calculated marks',value:n(r),details:[['Maximum marks',n(+v.total*+v.marks)],['Unanswered questions',+v.total-+v.correct-+v.wrong],['Marks gained',n(+v.correct*+v.marks)],['Penalty',n(+v.wrong*+v.penalty)]],copy:String(r)});},{label:'Calculate exam score'}),
 'attendance-target':()=>form(mount,[num('attended','Classes attended',60,0,100000,1),num('total','Classes held',80,1,100000,1),num('target','Target attendance (%)',75,1,100)],v=>{const r=attendance(+v.attended,+v.total,+v.target);show({label:'Current attendance',value:n(r.percent)+'%',details:[['Future classes to attend in a row',r.needed===null?'Cannot reach 100% after a missed class':r.needed],['Classes you can miss now',r.canMiss],['Target',v.target+'%']],copy:`${r.percent.toFixed(2)}%; attend next ${r.needed??'unattainable'}; can miss ${r.canMiss}`});},{label:'Calculate attendance plan'}),
 'citation-formatter':()=>form(mount,[sel('style','Citation style',[['apa','APA 7'],['mla','MLA 9']],'apa'),sel('type','Source type',[['web','Webpage'],['book','Book'],['journal','Journal article']],'web'),text('author','Author (Last, First; separate authors with semicolons)','Kunwar, Nabin','text',true),text('title','Page, book or article title','A guide to useful online tools','text',true),text('container','Website or journal title','Nepocore','text',true),text('date','Publication date',today(),'date'),optional(text('publisher','Publisher (books)','Example Press')),optional(text('volume','Journal volume','12')),optional(text('issue','Journal issue','2')),optional(text('pages','Page range','10–20')),optional(text('url','URL or DOI URL','https://nepocore.com/','url',true))],v=>{if(v.url)need(/^https?:\/\//i.test(v.url),'Use an HTTP(S) URL.');const d=new Date(v.date+'T00:00:00Z'),year=d.getUTCFullYear(),apaDate=d.toLocaleDateString('en-US',{year:'numeric',month:'long',day:'numeric',timeZone:'UTC'}),mlaDate=d.toLocaleDateString('en-GB',{year:'numeric',month:'short',day:'numeric',timeZone:'UTC'}),a=authorNames(v.author,v.style),title=v.title.trim();let c;if(v.style==='apa')c=v.type==='web'?`${a}. (${apaDate.replace(/^(\w+) (\d+), (\d+)$/,'$3, $1 $2')}). ${title}. ${v.container}. ${v.url}`:v.type==='book'?`${a}. (${year}). ${title}. ${v.publisher}. ${v.url}`:`${a}. (${year}). ${title}. ${v.container}, ${v.volume}${v.issue?'('+v.issue+')':''}${v.pages?', '+v.pages:''}. ${v.url}`;else c=v.type==='web'?`${a}. “${title}.” ${v.container}, ${mlaDate}, ${v.url}.`:v.type==='book'?`${a}. ${title}. ${v.publisher}, ${year}. ${v.url}`:`${a}. “${title}.” ${v.container}, vol. ${v.volume}${v.issue?', no. '+v.issue:''}, ${year}${v.pages?', pp. '+v.pages:''}. ${v.url}`;outputText(out,c.trim(),[['Scope','Common source patterns; review author initials and title styling']]);},{label:'Build citation',note:'Enter author names in the form required by your style (APA generally uses initials). This formatter handles basic patterns; italics and complex author lists need review.'}),
 'ohms-law':()=>form(mount,[sel('a','First known value',[['V','Voltage (V)'],['I','Current (A)'],['R','Resistance (Ω)'],['P','Power (W)']],'V'),num('av','First value',12,.000000001,1e12),sel('b','Second known value',[['V','Voltage (V)'],['I','Current (A)'],['R','Resistance (Ω)'],['P','Power (W)']],'R'),num('bv','Second value',6,.000000001,1e12)],v=>{const r=ohm(v.a,v.b,+v.av,+v.bv);show({label:'Voltage',value:n(r.V)+' V',details:[['Current',n(r.I)+' A'],['Resistance',n(r.R)+' Ω'],['Power',n(r.P)+' W']],copy:JSON.stringify(r,null,2),note:'Simple resistive DC model: V = I × R; P = V × I.'});},{label:'Solve circuit values'}),
 'resistor-colors':()=>{const digits=['Black','Brown','Red','Orange','Yellow','Green','Blue','Violet','Grey','White'],colors=digits.map((x,i)=>[i,x]);return form(mount,[sel('bands','Band count',[4,5],4),sel('a','First digit',colors.slice(1),1),sel('b','Second digit',colors,0),sel('c','Third digit (five-band only)',colors,0),sel('multiplier','Multiplier',[[0,'Black ×1'],[1,'Brown ×10'],[2,'Red ×100'],[3,'Orange ×1k'],[4,'Yellow ×10k'],[5,'Green ×100k'],[6,'Blue ×1M'],[7,'Violet ×10M'],[8,'Grey ×100M'],[9,'White ×1G'],[-1,'Gold ×0.1'],[-2,'Silver ×0.01']],2),sel('tolerance','Tolerance',[[1,'Brown ±1%'],[2,'Red ±2%'],[.5,'Green ±0.5%'],[.25,'Blue ±0.25%'],[.1,'Violet ±0.1%'],[.05,'Grey ±0.05%'],[5,'Gold ±5%'],[10,'Silver ±10%']],5)],v=>{const base=v.bands==='5'?+v.a*100+ +v.b*10+ +v.c:+v.a*10+ +v.b,value=base*10**+v.multiplier;show({label:'Nominal resistance',value:n(value)+' Ω',details:[['Tolerance','±'+v.tolerance+'%'],['Minimum',n(value*(1-+v.tolerance/100))+' Ω'],['Maximum',n(value*(1+ +v.tolerance/100))+' Ω']],copy:value+' ohms ±'+v.tolerance+'%'});},{label:'Decode resistor'});},
 'led-resistor':()=>form(mount,[num('supply','Supply voltage (V)',5,.1,60),num('drop','LED forward voltage (V)',2,.1,50),num('current','Desired current (mA)',20,.01,1000)],v=>{need(+v.supply>+v.drop,'Supply voltage must exceed the LED forward voltage.');const amps=+v.current/1000,r=(+v.supply-+v.drop)/amps,p=(+v.supply-+v.drop)*amps,e12=[1,1.2,1.5,1.8,2.2,2.7,3.3,3.9,4.7,5.6,6.8,8.2],scale=10**Math.floor(Math.log10(r)),standard=[...e12.map(x=>x*scale),10*scale].find(x=>x>=r-1e-9);show({label:'Calculated series resistance',value:n(r)+' Ω',details:[['Next E12 value at or above result',n(standard)+' Ω'],['Calculated resistor dissipation',n(p)+' W'],['Current with selected E12 value',n((+v.supply-+v.drop)/standard*1000)+' mA']],copy:`${r} Ω; E12 ${standard} Ω; dissipation ${p} W`,note:'Use component datasheets and a resistor power rating with appropriate margin. For simple low-voltage DC circuits only.'});},{label:'Calculate series resistor'}),
 'kinetic-energy':()=>form(mount,[sel('find','Find',[['energy','Energy (J)'],['mass','Mass (kg)'],['speed','Speed (m/s)']],'energy'),num('mass','Mass (kg)',2,0,1e12),num('speed','Speed (m/s)',3,0,1e7),num('energy','Energy (J)',9,0,1e25)],v=>{let r,unit;if(v.find==='energy'){r=.5*+v.mass*(+v.speed)**2;unit='J';}else if(v.find==='mass'){need(+v.speed>0,'Speed must be positive to calculate mass.');r=2*+v.energy/((+v.speed)**2);unit='kg';}else{need(+v.mass>0,'Mass must be positive to calculate speed.');r=Math.sqrt(2*+v.energy/+v.mass);unit='m/s';}show({label:'Calculated '+v.find,value:n(r)+' '+unit,details:[['Equation','E = ½mv²']],copy:r+' '+unit});},{label:'Calculate energy, mass or speed',note:'Only the two known fields are used. The value being calculated is ignored.'}),
 'projectile-motion':()=>form(mount,[num('speed','Launch speed (m/s)',20,.01,1000),num('angle','Launch angle (degrees)',45,0,90),num('height','Launch height (m)',0,0,10000),num('gravity','Gravity (m/s²)',9.80665,.01,100)],v=>{const r=projectile(+v.speed,+v.angle,+v.height,+v.gravity),sx=Math.max(1,r.range),sy=Math.max(1,r.apex),points=r.points.map(p=>(35+p.x/sx*420).toFixed(2)+','+(245-p.y/sy*200).toFixed(2)).join(' ');show({label:'Ideal horizontal range',value:n(r.range)+' m',details:[['Flight time',n(r.flight)+' s'],['Maximum height',n(r.apex)+' m']],html:`<svg class="trajectory-plot" viewBox="0 0 500 285" role="img" aria-label="Ideal projectile trajectory, height versus horizontal distance"><path d="M35 20v225h430"/><polyline points="${points}"/><text x="40" y="275">0</text><text x="350" y="275">${n(r.range)} m</text><text x="40" y="18">${n(r.apex)} m height</text></svg>`,copy:JSON.stringify({range:r.range,flight:r.flight,apex:r.apex},null,2),note:'Idealized trajectory: constant gravity, no air resistance or wind.'});},{label:'Explore trajectory'})
 };need(forms[id],'This learning tool is unavailable.');forms[id]();}
function typing(mount,out){const samples=['Useful tools help us focus on the work that matters. Small improvements become good habits when we practice with patience and care.','A clear idea is the beginning of a useful project. Build a little, test your work, and keep learning from the result.'];let running=false,start=0,timer,limit=30;mount.innerHTML='<h2>A little practice, every day</h2><div class="form-grid">'+[sel('duration','Time limit (seconds)',[30,60,120],30),sel('sample','Passage',[[0,'Useful tools'],[1,'A clear idea']],0)].map(field).join('')+'</div><p class="typing-passage"></p><label class="field"><span>Type the passage here</span><textarea data-typing disabled spellcheck="false" autocomplete="off"></textarea></label><p data-timer class="form-note">Ready</p><div class="form-actions"><button class="btn primary" data-start>Start test</button><button class="btn secondary" data-finish disabled>Finish test</button></div>';const input=mount.querySelector('textarea'),passage=mount.querySelector('.typing-passage'),clock=mount.querySelector('[data-timer]'),begin=mount.querySelector('[data-start]'),finish=mount.querySelector('[data-finish]');function update(final=false){const seconds=Math.max(.1,Math.min(limit,(performance.now()-start)/1000)),typed=Array.from(input.value),expected=Array.from(passage.textContent),correct=typed.reduce((s,c,i)=>s+(c===expected[i]?1:0),0);clock.textContent=Math.max(0,limit-seconds).toFixed(1)+' seconds remaining';if(final)result(out,{label:'Gross typing speed',value:n(typed.length/5/(seconds/60))+' WPM',details:[['Character accuracy',typed.length?n(correct/typed.length*100)+'%':'0%'],['Typed characters',typed.length],['Correct characters',correct],['Elapsed',seconds.toFixed(1)+' s']],copy:`${(typed.length/5/(seconds/60)).toFixed(1)} WPM; ${typed.length?(correct/typed.length*100).toFixed(1):0}% accuracy`,note:'Gross WPM uses five characters per word. Accuracy compares character positions with the visible passage.'});if(seconds>=limit&&running)stop();}function stop(){if(!running)return;running=false;clearInterval(timer);update(true);input.disabled=true;finish.disabled=true;begin.disabled=false;}function sample(){passage.textContent=samples[+mount.querySelector('[name=sample]').value];}mount.querySelector('[name=sample]').onchange=()=>{if(!running)sample();};begin.onclick=()=>{clearInterval(timer);sample();limit=+mount.querySelector('[name=duration]').value;input.value='';input.disabled=false;begin.disabled=true;finish.disabled=false;start=performance.now();running=true;input.focus();timer=setInterval(()=>update(),100);};finish.onclick=stop;sample();return()=>clearInterval(timer);}
function flashcards(mount,out){let cards=[],queue=[],current=null,revealed=false;mount.innerHTML='<h2>Build a small deck</h2><form><label class="field"><span>Question | answer — one per line</span><textarea name="cards" required>What does HTML stand for? | HyperText Markup Language\nWhat is a variable? | A named reference to a value\nWhat is HTTPS? | HTTP over an encrypted TLS connection</textarea></label><button class="btn primary" type="submit">Load deck</button><div class="form-error"></div></form><div class="form-actions"><button class="btn secondary small" data-all>Study all now</button><button class="btn secondary small" data-export>Export deck JSON</button></div>';let persist=()=>{};function render(){if(!queue.length){current=null;result(out,{label:'This round is complete',value:'Nice work.',details:[['Cards in deck',cards.length],['Due now',cards.filter(c=>c.due<=Date.now()).length]],html:'<p class="form-note">Use Study all now to practice again. Export the deck or opt in to saving it on this device.</p>',copy:cards.map(c=>c.front+' | '+c.back).join('\n')});return;}current=queue[0];const c=cards[current];result(out,{html:`<div class="flashcard"><span>Question · ${queue.length} left</span><h3>${e(c.front)}</h3>${revealed?`<p>${e(c.back)}</p>`:'<button class="btn primary" data-reveal>Reveal answer</button>'}</div>${revealed?'<div class="form-actions"><button class="btn secondary small" data-grade="again">Again · 10 min</button><button class="btn secondary small" data-grade="good">Good · next interval</button><button class="btn secondary small" data-grade="easy">Easy · longer interval</button></div>':''}`});out.querySelector('[data-reveal]')?.addEventListener('click',()=>{revealed=true;render();});out.querySelectorAll('[data-grade]').forEach(b=>b.onclick=()=>{const grade=b.dataset.grade;c.interval=grade==='again'?0:grade==='easy'?Math.max(4,c.interval*3):Math.max(1,c.interval*2);c.due=Date.now()+(grade==='again'?600000:c.interval*86400000);queue.shift();revealed=false;persist();render();});}function review(all=false){queue=cards.map((_,i)=>i).filter(i=>all||cards[i].due<=Date.now());revealed=false;render();}mount.querySelector('form').onsubmit=ev=>{ev.preventDefault();try{const lines=ev.currentTarget.elements.cards.value.trim().split(/\n/).filter(Boolean);need(lines.length>=1&&lines.length<=200,'Use 1–200 cards.');cards=lines.map(line=>{const parts=line.split(/\t|\|/);need(parts.length>=2&&parts[0].trim()&&parts.slice(1).join('|').trim(),'Use question | answer on every line.');return{front:parts[0].trim(),back:parts.slice(1).join('|').trim(),due:0,interval:0};});persist();review(true);}catch(ex){error(ev.currentTarget.querySelector('.form-error'),ex.message);}};mount.querySelector('[data-all]').onclick=()=>review(true);mount.querySelector('[data-export]').onclick=()=>download(new Blob([JSON.stringify(cards,null,2)],{type:'application/json'}),'nepocore-flashcards.json');const initial=new Event('submit',{cancelable:true});mount.querySelector('form').dispatchEvent(initial);persist=localChoice(mount,'nepocore-flashcards-v1',saved=>{if(Array.isArray(saved)&&saved.length<=200&&saved.every(c=>typeof c.front==='string'&&typeof c.back==='string'&&Number.isFinite(c.due)&&Number.isFinite(c.interval))){cards=saved;review();}},()=>cards);return()=>persist();}
